<?php
require_once __DIR__ . "/../../helpers/api.php";
require_once __DIR__ . "/../../models/ResearchProject.php";
apiRequireAuth(); $id=apiInt($_GET['id']??null,'project ID'); $model=new ResearchProject(); $project=$model->getProjectById($id); if(!$project) jsonResponse(["success"=>false,"message"=>"Project not found"],404); $role=(int)$_SESSION['role_id']; if($_SERVER['REQUEST_METHOD']==='GET'){ $allowed=($role===4)||($role===3&&(int)$project['supervisor_id']===(int)$_SESSION['user_id']); if($role===2)$allowed=(bool)apiFindById($model->getStudentProjects((int)$_SESSION['user_id']),$id); if(!$allowed)jsonResponse(["success"=>false,"message"=>"Access denied"],403); $progress=$model->calculateProjectProgress($id); jsonResponse(["success"=>true,"progress"=>(int)$progress]); }
if($_SERVER['REQUEST_METHOD']!=='PUT') jsonResponse(["success"=>false,"message"=>"Only GET or PUT requests are allowed"],405); if($role!==3 || (int)$project['supervisor_id']!==(int)$_SESSION['user_id']) jsonResponse(["success"=>false,"message"=>"Access denied"],403); $data=apiBody(); apiRequired($data,['progress']); $progress=filter_var($data['progress'],FILTER_VALIDATE_INT); if($progress===false||$progress<0||$progress>100)jsonResponse(["success"=>false,"message"=>"Progress must be between 0 and 100"],400); if(!$model->updateProgress($id,$progress))jsonResponse(["success"=>false,"message"=>"Failed to update project progress"],500); apiLog((int)$_SESSION['user_id'],'Updated research project ID: '.$id.' progress to '.$progress.'%'); jsonResponse(["success"=>true,"message"=>"Project progress updated","data"=>["id"=>$id,"progress"=>$progress]]);
?>
